void point2Arrow( geometryInS inputs[1], bool drawHeads, float scale, 
      float4x4 worldViewProjection, float3 cameraDirection, inout LineStream<geometryInS> outStream  ) 
{ 
    geometryInS out0  = inputs[0]; 
    outStream.Append( out0 ); 
    float3 dir = out0.velocity; 
    float4 arrow = inputs[0].Pc  + mul( float4(dir,0), worldViewProjection ) * scale; 
    out0.Pc = arrow; 
    outStream.Append( out0 ); 
    if(!drawHeads) return; 
    float4 base = 0.75 * arrow + 0.25 * inputs[0].Pc; 
    if(abs(cameraDirection.x) < abs(cameraDirection.z)) { 
		if(dir.y == 0.0 && dir.x == 0.0) 
			dir = float3(dir.z, 0.0, 0.0); 
		else 
			dir = float3(dir.y, -dir.x, 0.0); 
	 }else{ 
		if(dir.y == 0.0 && dir.z == 0.0) 
			dir = float3(0.0, 0.0, dir.x); 
		else 
			dir = float3(0.0, dir.z, -dir.y); 
	 } 
    float2 radius = 0.1*length(dir)*mul( float4(normalize(dir), 0.0), worldViewProjection ).xy; 
    out0.Pc = base  + float4(radius, 0.0, 0.0); 
    outStream.Append( out0 ); 
    out0.Pc = arrow; 
    outStream.Append( out0 ); 
    out0.Pc = base  - float4(radius, 0.0, 0.0); 
    outStream.Append( out0 ); 
    out0.Pc = arrow; 
    outStream.Append( out0 ); 
    outStream.RestartStrip(); 
}


void point2Arrow( AttribArray<geometryInS>inputs, bool drawHeads, float scale, 
      float4x4 worldViewProjection, float3 cameraDirection) 
{ 
    geometryInS out0  = inputs[0]; 
    emitVertex( out0 ); 
    float3 dir = out0.velocity; 
    float4 arrow = inputs[0].Pc  + mul( worldViewProjection, float4(dir,0) ) * scale; 
    out0.Pc = arrow; 
    emitVertex( out0 ); 
    if(!drawHeads) return; 
    float4 base = 0.25 * inputs[0].Pc + 0.75 * arrow; 
    if(abs(cameraDirection.x) < abs(cameraDirection.z)) { 
		if(dir.y == 0.0 && dir.x == 0.0) 
			dir = float3(dir.z, 0.0, 0.0); 
		else 
			dir = float3(dir.y, -dir.x, 0.0); 
	 }else{ 
		if(dir.y == 0.0 && dir.z == 0.0) 
			dir = float3(0.0, 0.0, dir.x); 
		else 
			dir = float3(0.0, dir.z, -dir.y); 
	 } 
    float2 radius = 0.1*length(dir)*mul( worldViewProjection, float4(normalize(dir), 0.0) ).xy; 
    out0.Pc = base  + float4(radius, 0.0, 0.0); 
    emitVertex( out0 ); 
    out0.Pc = arrow; 
    emitVertex( out0 ); 
    out0.Pc = base  - float4(radius, 0.0, 0.0); 
    emitVertex( out0 ); 
    out0.Pc = arrow; 
    emitVertex( out0 ); 
    restartStrip(); 
}


void point2Arrow(  bool drawHeads, float scale, 
      mat4x4 worldViewProjection, vec3 cameraDirection) 
{ 
    GEO_OUT_struct out0  = copyFromGEO_IN(0); 
    EmitGeoStruct( out0 ); 
    vec3 dir = out0.velocity; 
    vec4 arrow = gl_in[0].gl_Position  + mul( worldViewProjection, vec4(dir,0) ) * scale; 
    out0.Pc = arrow; 
    EmitGeoStruct( out0 ); 
    if(!drawHeads) return; 
    vec4 base = 0.25 * gl_in[0].gl_Position + 0.75 * arrow; 
    if(abs(cameraDirection.x) < abs(cameraDirection.z)) { 
		if(dir.y == 0.0 && dir.x == 0.0) 
			dir = vec3(dir.z, 0.0, 0.0); 
		else 
			dir = vec3(dir.y, -dir.x, 0.0); 
	 }else{ 
		if(dir.y == 0.0 && dir.z == 0.0) 
			dir = vec3(0.0, 0.0, dir.x); 
		else 
			dir = vec3(0.0, dir.z, -dir.y); 
	 } 
    vec2 radius = 0.1*length(dir)*mul( worldViewProjection, vec4(normalize(dir), 0.0) ).xy; 
    out0.Pc = base  + vec4(radius, 0.0, 0.0); 
    EmitGeoStruct( out0 ); 
    out0.Pc = arrow; 
    EmitGeoStruct( out0 ); 
    out0.Pc = base  - vec4(radius, 0.0, 0.0); 
    EmitGeoStruct( out0 ); 
    out0.Pc = arrow; 
    EmitGeoStruct( out0 ); 
    EndPrimitive(); 
}


